INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (7001, "2015/12/17 15:00:00", 1, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "2030/12/17 14:59:59", 0, 7, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (7002, "2015/12/17 15:00:00", 1, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "2030/12/17 14:59:59", 0, 7, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (7003, "2015/12/17 15:00:00", 1, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "2030/12/17 14:59:59", 0, 7, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10001, "2015/12/17 15:00:00", 1, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "2030/12/17 14:59:59", 0, 10, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10002, "2015/12/17 15:00:00", 1, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "2030/12/17 14:59:59", 0, 10, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10003, "2015/12/17 15:00:00", 1, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "2030/12/17 14:59:59", 0, 10, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10004, "2015/12/17 15:00:00", 1, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "2030/12/17 14:59:59", 0, 10, 2104010, 0, -363, 106401, 2, 0, "シェフィ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (12001, "2015/12/17 15:00:00", 1, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "2030/12/17 14:59:59", 0, 12, 0, 0, -416.5, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13001, "2015/12/17 15:00:00", 1, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "2030/12/17 14:59:59", 0, 13, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13002, "2015/12/17 15:00:00", 1, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "2030/12/17 14:59:59", 0, 13, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13003, "2015/12/17 15:00:00", 1, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "2030/12/17 14:59:59", 0, 13, 2104010, 0, -363, 106401, 2, 0, "シェフィ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13004, "2015/12/17 15:00:00", 1, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "2030/12/17 14:59:59", 0, 13, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14001, "2015/12/17 15:00:00", 1, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "2030/12/17 14:59:59", 0, 14, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14002, "2015/12/17 15:00:00", 1, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "2030/12/17 14:59:59", 0, 14, 2104010, 0, -363, 106401, 2, 0, "シェフィ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14003, "2015/12/17 15:00:00", 1, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "2030/12/17 14:59:59", 0, 14, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14004, "2015/12/17 15:00:00", 1, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "2030/12/17 14:59:59", 0, 14, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (15001, "2015/12/17 15:00:00", 1, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "2030/12/17 14:59:59", 0, 15, 0, 0, -470, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16001, "2015/12/17 15:00:00", 1, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "2030/12/17 14:59:59", 0, 16, 2104010, 0, -363, 106401, 2, 0, "シェフィ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16002, "2015/12/17 15:00:00", 1, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "2030/12/17 14:59:59", 0, 16, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16003, "2015/12/17 15:00:00", 1, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "2030/12/17 14:59:59", 0, 16, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16004, "2015/12/17 15:00:00", 1, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "2030/12/17 14:59:59", 0, 16, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (17002, "2015/12/17 15:00:00", 1, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "2030/12/17 14:59:59", 0, 17, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (17004, "2015/12/17 15:00:00", 1, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "2030/12/17 14:59:59", 0, 25, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (17005, "2015/12/17 15:00:00", 1, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "2030/12/17 14:59:59", 0, 25, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (17006, "2015/12/17 15:00:00", 1, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "2030/12/17 14:59:59", 0, 25, 2104010, 0, -363, 106401, 2, 0, "シェフィ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (17007, "2015/12/17 15:00:00", 1, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "2030/12/17 14:59:59", 0, 25, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (18001, "2015/12/17 15:00:00", 1, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "2030/12/17 14:59:59", 0, 18, 0, 0, -363, 190801, 1, 0, "カリン", 1);
