INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (19001, "2015/12/17 15:00:00", 1, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "2030/12/17 14:59:59", 0, 19, 0, 0, -470, 190801, 1, 0, "カリン", 3);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (19002, "2015/12/17 15:00:00", 1, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "2030/12/17 14:59:59", 0, 19, 0, 0, -470, 190801, 1, 0, "カリン", 4);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (20001, "2015/12/17 15:00:00", 1, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "2030/12/17 14:59:59", 0, 20, 0, 0, -470, 190801, 1, 0, "カリン", 5);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (20002, "2015/12/17 15:00:00", 1, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "2030/12/17 14:59:59", 0, 20, 0, 0, -470, 190801, 1, 0, "カリン", 6);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21001, "2015/12/17 15:00:00", 1, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "2030/12/17 14:59:59", 0, 21, 0, 0, -363, 106001, 1, 0, "キャル", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21002, "2015/12/17 15:00:00", 1, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "2030/12/17 14:59:59", 0, 21, 0, 0, -363, 105901, 1, 0, "コッコロ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21003, "2015/12/17 15:00:00", 1, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "2030/12/17 14:59:59", 0, 21, 2104010, 0, -363, 106401, 2, 0, "シェフィ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21004, "2015/12/17 15:00:00", 1, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "2030/12/17 14:59:59", 0, 21, 0, 0, -363, 105801, 1, 0, "ペコリーヌ", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (22001, "2015/12/17 15:00:00", 1, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "2030/12/17 14:59:59", 0, 22, 0, 0, -430, 190801, 1, 0, "カリン", 1);
