INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (23001, "2015/12/17 15:00:00", 1, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "2030/12/17 14:59:59", 0, 23, 0, 0, -430, 190801, 1, 0, "カリン", 3);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (23002, "2015/12/17 15:00:00", 1, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "2030/12/17 14:59:59", 0, 23, 0, 0, -430, 190801, 1, 0, "カリン", 4);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24001, "2019/01/31 12:00:00", 2, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "2030/12/17 14:59:59", 8, 24, 0, 4.08, -385, 109001, 1, 10011, "エリコ（バレンタイン）", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24002, "2019/01/31 12:00:00", 2, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "2030/12/17 14:59:59", 8, 24, 0, 5, -385, 109001, 1, 10011, "エリコ（バレンタイン）", 2);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24003, "2019/01/31 12:00:00", 2, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "2030/12/17 14:59:59", 8, 24, 0, 10.11, -385, 109001, 1, 10011, "エリコ（バレンタイン）", 3);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24004, "2019/01/31 12:00:00", 2, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "2030/12/17 14:59:59", 8, 24, 0, 4, -385, 109001, 1, 10011, "エリコ（バレンタイン）", 4);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24005, "2019/01/31 12:00:00", 2, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "2030/12/17 14:59:59", 8, 24, 0, 6, -385, 109001, 1, 10011, "エリコ（バレンタイン）", 5);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24006, "2019/01/31 12:00:00", 1, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109002, 1, 10011, "エリコ（バレンタイン）", 6);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24007, "2019/01/31 12:00:00", 1, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109002, 1, 10011, "エリコ（バレンタイン）", 7);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24008, "2019/01/31 12:00:00", 1, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109002, 1, 10011, "エリコ（バレンタイン）", 8);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24009, "2019/01/31 12:00:00", 1, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109002, 1, 10011, "エリコ（バレンタイン）", 9);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24010, "2019/01/31 12:00:00", 1, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109002, 1, 10011, "エリコ（バレンタイン）", 10);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24011, "2019/01/31 12:00:00", 2, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "2030/12/17 14:59:59", 8, 24, 0, 2.12, -385, 109101, 1, 10011, "シズル（バレンタイン）", 1);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24012, "2019/01/31 12:00:00", 2, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "2030/12/17 14:59:59", 8, 24, 0, 4.19, -385, 109101, 5, 10011, "シズル（バレンタイン）", 2);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24013, "2019/01/31 12:00:00", 4, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "2030/12/17 14:59:59", 8, 24, 0, 2.3, -385, 109101, 2, 10011, "シズル（バレンタイン）", 3);
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24014, "2019/01/31 12:00:00", 1, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109102, 1, 10011, "シズル（バレンタイン）", 4);
