INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24019, "2019/01/31 12:00:00", 1, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "2030/12/17 14:59:59", 0, 24, 0, 0, 0, 109102, 1, 10011, "シズル（バレンタイン）", 9);
